import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Export to OpenAPI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/export-openapi.md","filePath":"guide/export-openapi.md","lastUpdated":1785990345000}'),i={name:"guide/export-openapi.md"};function s(r,e,p,l,d,h){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="export-to-openapi" tabindex="-1">Export to OpenAPI <a class="header-anchor" href="#export-to-openapi" aria-label="Permalink to &quot;Export to OpenAPI&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta feature</p><p>The OpenAPI channel is disabled by default. Enable it in the <strong>Features</strong> tab before using it.</p></div><p>EasyYapi exports HTTP endpoints as an <a href="https://www.openapis.org/" target="_blank" rel="noreferrer">OpenAPI</a> 3.0.3 document. The result can be consumed by OpenAPI tooling, imported into API gateways, or checked into a repository as an API contract.</p><h2 id="enable-the-channel" tabindex="-1">Enable the channel <a class="header-anchor" href="#enable-the-channel" aria-label="Permalink to &quot;Enable the channel&quot;">​</a></h2><p>Open <strong>Settings</strong> &gt; <strong>Other Settings</strong> &gt; <strong>EasyApi</strong> &gt; <strong>Features</strong>. Under <strong>Export Channels</strong>, enable <strong>OpenAPI (Beta)</strong>. The channel then appears in the export dialog and as the OpenAPI export action.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><ol><li>Open a file containing API endpoints, or select files/folders in the Project view.</li><li>Choose <strong>EasyYapi</strong> &gt; <strong>Export</strong> &gt; <strong>OpenAPI (Beta)</strong>, or use the OpenAPI action from the API Dashboard.</li><li>Select an output format when prompted, unless a format has already been saved in the OpenAPI settings.</li><li>Choose the destination file.</li></ol><p>JSON is written to <code>openapi.json</code>; YAML is written to <code>openapi.yaml</code> by default. You can override the output directory and file name in the export dialog.</p><p>The channel is HTTP-only. gRPC endpoints are skipped because they cannot be represented by this OpenAPI exporter. If the selection contains no HTTP endpoints, the export reports that there is nothing to export.</p><h2 id="output-mapping" tabindex="-1">Output mapping <a class="header-anchor" href="#output-mapping" aria-label="Permalink to &quot;Output mapping&quot;">​</a></h2><p>The exporter creates an OpenAPI 3.0.3 document with:</p><ul><li><code>info.title</code>, <code>info.version</code>, and an optional description</li><li>an optional <code>servers</code> entry</li><li>paths and operations with unique operation IDs</li><li>query, path, header, and cookie parameters</li><li>JSON request bodies</li><li><code>application/x-www-form-urlencoded</code> and multipart request bodies, including file fields</li><li>response schemas and reusable component schemas</li><li>tags derived from the API folder or source class</li><li>enum values and parameter examples when they are available</li></ul><p>Path parameters are always marked as required, as required by the OpenAPI specification. Void responses are emitted as <code>204 No content</code> when no response model is available.</p><h2 id="document-metadata-rules" tabindex="-1">Document metadata rules <a class="header-anchor" href="#document-metadata-rules" aria-label="Permalink to &quot;Document metadata rules&quot;">​</a></h2><p>Use project rules when the document envelope needs a stable value that should not depend on the current export selection:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.info.title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Public API</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.info.version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2026.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.info.description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=HTTP API for the public application</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.server.url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://api.example.com</span></span></code></pre></div><p>The preferred server rule is <code>openapi.server.url</code>. The legacy <code>openapi.host</code> key is also accepted. The <code>openapi.format.after</code> event runs after the document is built and before it is serialized, so advanced rules can adjust the in-memory document before JSON or YAML output is written.</p><p>See <a href="/settings/config-rule">Config Rules</a> for rule syntax.</p>`,18)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
